#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_NAME_LEN 50
#define NUM_GRADES 5

typedef struct {
    char name[MAX_NAME_LEN];
    int id;
    double grades[NUM_GRADES];
    double average;
    union {
        char passFail;
        int gradeCategory;
    } status;
} Student;

void inputStudentData(Student *s, int n) {
    for (int i = 0; i < n; i++) {
        scanf("%49s", s[i].name);
        scanf("%d", &s[i].id);
        for (int j = 0; j < NUM_GRADES; j++) {
            scanf("%lf", &s[i].grades[j]);
        }
    }
}

void calculateAverage(Student *s, int n) {
    for (int i = 0; i < n; i++) {
        double sum = 0.0;
        for (int j = 0; j < NUM_GRADES; j++) {
            sum += s[i].grades[j];
        }
        s[i].average = sum / NUM_GRADES;
    }
}

void determineStatus(Student *s, int n) {
    for (int i = 0; i < n; i++) {
        double avg = s[i].average;
        if (avg >= 50.0) {
            if (avg >= 85.0) {
                s[i].status.gradeCategory = 1;
            } else if (avg >= 70.0) {
                s[i].status.gradeCategory = 2;
            } else if (avg >= 50.0) {
                s[i].status.gradeCategory = 3;
            }
        } else {
            s[i].status.passFail = 'F';
        }
    }
}

void displayStudents(const Student *s, int n) {
    for (int i = 0; i < n; i++) {
        double avg = s[i].average;
        if (avg >= 50.0) {
            printf("Student: %s\n", s[i].name);
            printf("ID: %d\n", s[i].id);
            printf("Grades: ");
            for (int j = 0; j < NUM_GRADES; j++) {
                printf("%.1f", s[i].grades[j]);
                if (j < NUM_GRADES - 1) {
                    printf(", ");
                }
            }
            printf("\n");
            printf("Average: %.1f\n", avg);
            printf("Status: Grade Category - %d \n", s[i].status.gradeCategory);
        } else {
            printf("Student: %s\n", s[i].name);
            printf("ID: %d\n", s[i].id);
            printf("Grades: ");
            for (int j = 0; j < NUM_GRADES; j++) {
                printf("%.1f", s[i].grades[j]);
                if (j < NUM_GRADES - 1) {
                    printf(", ");
                }
            }
            printf("\n");
            printf("Average: %.1f\n", avg);
            printf("Status: Pass/Fail - %c\n", s[i].status.passFail);
        }
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }
    Student *students = (Student *)malloc(n * sizeof(Student));
    if (students == NULL) {
        return 1;
    }
    inputStudentData(students, n);
    calculateAverage(students, n);
    determineStatus(students, n);
    displayStudents(students, n);
    free(students);
    return 0;
}
